begin;
insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'ae6cfc11-f9ca-40d2-841c-cc50953ed22f', encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Internal energy and specific latent heat', 'What is the unit of specific latent heat?', 'J/°C', 'W/kg', 'J/kg', 'J/kg °C', 'C', 'Specific latent heat is the energy needed to change the state of 1 kg of a substance, so it is measured in joules per kilogram. J/kg °C is the unit of specific heat capacity.', 'foundation', 'recall', 'AO1'),
  (2, 'Particle motion in gases and gas pressure', 'A gas in a sealed container is cooled. What happens to the average speed of its particles?', 'It reverses direction', 'It decreases', 'It stays the same', 'It increases', 'B', 'The temperature of a gas is related to the average kinetic energy of its particles, so cooling it makes the particles move more slowly.', 'foundation', 'applied', 'AO2'),
  (3, 'Particle motion in gases and gas pressure', 'A fixed mass of gas is compressed to half its volume at constant temperature. What happens to its pressure?', 'It doubles', 'It stays the same', 'It halves', 'It quadruples', 'A', 'At constant temperature, pressure × volume is constant, so halving the volume doubles the pressure.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.name = v.sub
join topics t on t.id = s.topic_id
join subjects j on j.id = t.subject_id and j.name = 'Physics'
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

-- One quiz per subtopic (quizzes.subtopic_id set), holding every active
-- question in the subtopic, oldest first. Skips a subtopic that already has one.
with v(sub, title, ord) as (values
  ('Internal energy and specific latent heat', 'Internal energy and specific latent heat quiz', 12),
  ('Particle motion in gases and gas pressure', 'Particle motion in gases and gas pressure quiz', 13)
), ins as (
  insert into quizzes (topic_id, subtopic_id, title, display_order, question_count, cooldown_hours)
  select t.id, s.id, v.title, v.ord, 0, 168
  from v
  join subtopics s on s.name = v.sub
  join topics t on t.id = s.topic_id
  join subjects j on j.id = t.subject_id and j.name = 'Physics'
  where not exists (select 1 from quizzes z where z.subtopic_id = s.id)
  returning id, subtopic_id
)
insert into quiz_questions (quiz_id, question_id, position)
select ins.id, q.id, row_number() over (partition by ins.id order by q.created_at, q.id)
from ins join questions q on q.subtopic_id = ins.subtopic_id and q.active;

update quizzes z set question_count = (select count(*) from quiz_questions qq join questions q on q.id = qq.question_id where qq.quiz_id = z.id and q.active)
where z.subtopic_id is not null and z.question_count = 0;
commit;
